package org.usbworkbench;

import java.io.IOException;
import java.nio.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.CRC32;

/** Bounded metadata-only USB analysis. Never writes, syncs, mounts, or repairs a drive. */
public final class UsbAnalyzer {
    public static final String PREFIX="USB_ANALYSIS\n";
    private final BlockDevice disk;private final DiskTools.Progress progress;
    private final StringBuilder out=new StringBuilder(PREFIX);
    private final List<Part> parts=new ArrayList<>();
    public static final class Space {public final long total,free;public final String label;public final int flags;public Space(long t,long f,String l,int flags){total=t;free=f;label=l;this.flags=flags;}}
    public interface SpaceProbe {Space inspect(BlockDevice volume)throws IOException;}
    private final SpaceProbe probe;
    private long reads;private static final long BUDGET=64L*1048576;
    private static final class Part {int number;long first,count;Part(int n,long f,long c){number=n;first=f;count=c;}}
    public UsbAnalyzer(BlockDevice d,DiskTools.Progress p){this(d,p,null);}
    public UsbAnalyzer(BlockDevice d,DiskTools.Progress p,SpaceProbe probe){disk=d;progress=p;this.probe=probe;}
    public static String clean(String s){if(s==null)return "";StringBuilder b=new StringBuilder();for(int i=0;i<Math.min(s.length(),256);i++){char c=s.charAt(i);if(c>=32&&c!=127&&!(c>=0x202a&&c<=0x202e)&&!(c>=0x2066&&c<=0x2069))b.append(c);}return b.toString().trim();}
    public void field(String en,String ar,Object value){if(value==null||String.valueOf(value).isEmpty())field(en,ar,"Unavailable","غير متاح");else field(en,ar,String.valueOf(value),String.valueOf(value));}
    public void field(String en,String ar,String ev,String av){out.append(clean(en)).append('\t').append(clean(ar)).append('\t').append(clean(ev)).append('\t').append(clean(av)).append('\n');}
    private void note(String en,String ar){field(en,ar,"","");}
    private static long u32(byte[] b,int p){return (b[p]&255L)|(b[p+1]&255L)<<8|(b[p+2]&255L)<<16|(b[p+3]&255L)<<24;}
    private static int u16(byte[] b,int p){return (b[p]&255)|(b[p+1]&255)<<8;}
    private static long u64(byte[] b,int p)throws IOException{long v=ByteBuffer.wrap(b,p,8).order(ByteOrder.LITTLE_ENDIAN).getLong();if(v<0)throw new IOException("ANALYZER_METADATA");return v;}
    private static long crc(byte[] b){CRC32 c=new CRC32();c.update(b);return c.getValue();}
    private static String ascii(byte[] b,int at,int len){return clean(new String(b,at,len,StandardCharsets.US_ASCII));}
    private static String utf(byte[] b,int at,int len){String s=new String(b,at,len,StandardCharsets.UTF_16LE);int end=s.indexOf(0);return clean(end<0?s:s.substring(0,end));}
    private static String guid(byte[] b,int p){ByteBuffer x=ByteBuffer.wrap(b,p,16).order(ByteOrder.LITTLE_ENDIAN);long a=x.getInt()&0xffffffffL;int c=x.getShort()&65535,d=x.getShort()&65535;StringBuilder s=new StringBuilder(String.format(Locale.ROOT,"%08x-%04x-%04x-",a,c,d));for(int i=8;i<16;i++){if(i==10)s.append('-');s.append(String.format(Locale.ROOT,"%02x",b[p+i]&255));}return s.toString();}
    private byte[] read(long byteAt,int length)throws IOException{
        progress.update(reads,-1);int bs=disk.blockSize();long size=disk.blockCount()*bs;
        if(byteAt<0||length<0||byteAt>size||length>size-byteAt)throw new IOException("ANALYZER_METADATA");
        long start=byteAt/bs;int skip=(int)(byteAt%bs),n=(skip+length+bs-1)/bs*bs;
        if(n>1048576||reads>BUDGET-n)throw new IOException("ANALYZER_LIMIT");byte[] b=new byte[n];reads+=n;disk.read(start,b,n);return Arrays.copyOfRange(b,skip,skip+length);
    }
    private byte[] volume(Part p,long at,int n)throws IOException{long size=p.count*disk.blockSize();if(at<0||at>size||n>size-at)throw new IOException("ANALYZER_METADATA");return read(p.first*disk.blockSize()+at,n);}
    private void size(String en,String ar,long bytes){field(en,ar,String.format(Locale.ROOT,"%d B | %.3f GB | %.3f GiB",bytes,bytes/1e9,bytes/1073741824.0));}
    private void unknown(){field("Free / used space","المساحة الحرة / المستخدمة","Unavailable from supported metadata; not zero","غير متاحة من البيانات الوصفية المدعومة؛ ليست صفراً");}
    private void space(long total,long free,String en,String ar){if(total<0||free<0||free>total)throw new IllegalArgumentException();size("Filesystem allocation area","منطقة تخصيص نظام الملفات",total);size("Free space","المساحة الحرة",free);size("Allocated space (includes metadata)","المساحة المخصصة (تشمل البيانات الوصفية)",total-free);field("Space source","مصدر المساحة",en,ar);}
    private void add(int n,long first,long count){if(first<1||count<1||first>=disk.blockCount()||count>disk.blockCount()-first){note("Warning: partition outside drive or empty; skipped","تحذير: قسم خارج الوحدة أو فارغ؛ تم تجاوزه");return;}if(parts.size()>=128){note("Partition limit reached (128)","تم بلوغ حد الأقسام (128)");return;}parts.add(new Part(n,first,count));}
    private static boolean extended(int type){return type==5||type==15||type==0x85;}
    private void mbr(byte[] b)throws IOException{
        field("Partition table","جدول الأقسام","MBR");field("MBR disk signature","توقيع هوية قرص MBR",String.format(Locale.ROOT,"%08X",u32(b,440)));
        List<long[]> containers=new ArrayList<>();for(int i=0;i<4;i++){int at=446+i*16,type=b[at+4]&255;long first=u32(b,at+8),count=u32(b,at+12);if(type==0)continue;
            field("MBR entry / type / boot flag","إدخال MBR / النوع / راية الإقلاع",(i+1)+" / 0x"+Integer.toHexString(type)+" / 0x"+Integer.toHexString(b[at]&255));
            if(extended(type)){if(first>0&&count>0&&first<disk.blockCount()&&count<=disk.blockCount()-first)containers.add(new long[]{first,count});else note("Invalid extended partition bounds","حدود القسم الممتد غير صالحة");}else add(i+1,first,count);
        }
        int number=5;for(long[] container:containers){Set<Long> seen=new HashSet<>();long base=container[0],next=base,end=base+container[1];for(int step=0;step<64;step++){
            if(next<base||next>=end||!seen.add(next)){note("Invalid or cyclic extended partition chain","سلسلة أقسام ممتدة غير صالحة أو دائرية");break;}byte[] e=read(next*disk.blockSize(),512);if(u16(e,510)!=0xaa55){note("Invalid EBR signature","توقيع EBR غير صالح");break;}
            int type=e[450]&255;long rel=u32(e,454),count=u32(e,458),first=next+rel;
            if(type!=0&&!extended(type)&&rel>0&&first<end&&count>0&&count<=end-first)add(number++,first,count);else if(type!=0)note("Invalid logical partition bounds","حدود القسم المنطقي غير صالحة");
            int link=e[466]&255;if(link==0)break;if(!extended(link)){note("Invalid extended partition link","رابط القسم الممتد غير صالح");break;}next=base+u32(e,470);if(step==63)note("Extended chain limit reached (64)","تم بلوغ حد سلسلة الأقسام الممتدة (64)");
        }}
    }
    private byte[][] gptHeader(long lba)throws IOException{
        byte[] h=read(lba*disk.blockSize(),disk.blockSize());if(!ascii(h,0,8).equals("EFI PART"))throw new IOException("ANALYZER_METADATA");long len=u32(h,12),expected=u32(h,16);if(len<92||len>h.length||u64(h,24)!=lba||u64(h,32)>=disk.blockCount()||u64(h,40)>u64(h,48)||u64(h,48)>=disk.blockCount())throw new IOException("ANALYZER_METADATA");byte[] checked=Arrays.copyOf(h,(int)len);Arrays.fill(checked,16,20,(byte)0);if(crc(checked)!=expected)throw new IOException("ANALYZER_METADATA");
        long count=u32(h,80),entry=u32(h,84),start=u64(h,72);if(count<1||count>8192||entry<128||entry>4096||entry%128!=0||count*entry>1048576||start<2||start>=disk.blockCount()||count*entry>(disk.blockCount()-start)*disk.blockSize())throw new IOException("ANALYZER_METADATA");
        long tableSectors=(count*entry+disk.blockSize()-1)/disk.blockSize();long first=u64(h,40),last=u64(h,48);if(first<2||last>=disk.blockCount()-1||start<=lba&&lba<start+tableSectors||lba==1&&(start<=1||start+tableSectors>first)||lba!=1&&(start<=last||start+tableSectors>lba))throw new IOException("ANALYZER_METADATA");
        byte[] table=read(start*disk.blockSize(),(int)(count*entry));if(crc(table)!=u32(h,88))throw new IOException("ANALYZER_METADATA");return new byte[][]{h,table};
    }
    private void gpt()throws IOException{
        field("Partition table","جدول الأقسام","GPT");byte[][] primary=null,backup=null;
        try{primary=gptHeader(1);field("Primary GPT header and entries CRC32","CRC32 لترويسة GPT الأساسية وإدخالاتها","OK","سليم");}catch(IOException e){if(cancelled(e))throw e;note("Warning: primary GPT invalid or unreadable","تحذير: GPT الأساسية غير صالحة أو تعذرت قراءتها");}
        try{backup=gptHeader(disk.blockCount()-1);field("Backup GPT header and entries CRC32","CRC32 لترويسة GPT الاحتياطية وإدخالاتها","OK","سليم");}catch(IOException e){if(cancelled(e))throw e;note("Warning: backup GPT invalid or unreadable","تحذير: GPT الاحتياطية غير صالحة أو تعذرت قراءتها");}
        if(primary!=null&&backup!=null){boolean same=Arrays.equals(primary[1],backup[1])&&Arrays.equals(Arrays.copyOfRange(primary[0],40,72),Arrays.copyOfRange(backup[0],40,72))&&u64(primary[0],32)==disk.blockCount()-1&&u64(backup[0],32)==1;field("GPT copies agree","تطابق نسختي GPT",same?"Yes":"No — inconsistent metadata",same?"نعم":"لا — بيانات وصفية غير متطابقة");}
        byte[][] chosen=primary!=null?primary:backup;if(chosen==null){note("No verified GPT entries; no filesystem offsets guessed","لا توجد إدخالات GPT متحقق منها؛ لم تُخمّن مواقع أنظمة الملفات");return;}if(primary==null)note("Reading backup only; no repair performed","قراءة النسخة الاحتياطية فقط؛ لم يُجر إصلاح");
        byte[] h=chosen[0],entries=chosen[1];field("GPT disk GUID","معرف قرص GPT",guid(h,56));int es=(int)u32(h,84);int present=0;for(int at=0;at<entries.length;at+=es){boolean empty=true;for(int j=0;j<16;j++)if(entries[at+j]!=0)empty=false;if(empty)continue;present++;if(present>128)continue;int num=at/es+1;field("GPT entry / type GUID","إدخال GPT / معرف النوع",num+" / "+guid(entries,at));field("Partition GUID","معرف القسم",guid(entries,at+16));field("Partition name","اسم القسم",utf(entries,at+56,72));field("GPT attributes (hex)","سمات GPT (ست عشري)",Long.toHexString(ByteBuffer.wrap(entries,at+48,8).order(ByteOrder.LITTLE_ENDIAN).getLong()));long first=u64(entries,at+32),last=u64(entries,at+40);if(first<u64(h,40)||last>u64(h,48)||last<first)note("Invalid GPT partition bounds","حدود قسم GPT غير صالحة");else add(num,first,last-first+1);}
        if(present>128)note("Only first 128 populated GPT entries shown","عُرضت أول 128 خانة GPT مستخدمة فقط");
    }
    private static boolean cancelled(IOException e){return "CANCELLED".equals(e.getMessage());}
    private String signature(byte[] b){if(ascii(b,3,8).equals("NTFS"))return "NTFS";if(ascii(b,3,8).equals("EXFAT"))return "exFAT";if(b.length>=2048&&u16(b,1080)==0xef53)return "ext";if(b.length>=2048&&u32(b,1024)==0xf2f52010L)return "F2FS";if(ascii(b,0,4).equals("XFSB"))return "XFS";if(ascii(b,32,4).equals("NXSB"))return "APFS";if(ascii(b,3,8).equals("-FVE-FS-"))return "BitLocker";if(b[0]=='L'&&b[1]=='U'&&b[2]=='K'&&b[3]=='S'&&(b[4]&255)==0xba&&(b[5]&255)==0xbe)return "LUKS";if(b.length>=2048&&(ascii(b,1024,2).equals("H+")||ascii(b,1024,2).equals("HX")))return "HFS+";if(u16(b,510)==0xaa55&&(u16(b,11)==512||u16(b,11)==4096)&&(b[13]&255)>0&&((b[13]&255)&((b[13]&255)-1))==0&&u16(b,14)>0&&(b[16]&255)>0&&(b[16]&255)<=2&&(u16(b,22)>0||u32(b,36)>0))return "FAT";return "";}
    private final class FatCache {final Part p;final long base,length;long cached=-1;byte[] bytes;FatCache(Part p,long b,long n){this.p=p;base=b;length=n;}int get(long at)throws IOException{if(at<0||at>=length)throw new IOException("ANALYZER_METADATA");long chunk=at/65536*65536;if(chunk!=cached){bytes=volume(p,base+chunk,(int)Math.min(65536,length-chunk));cached=chunk;}return bytes[(int)(at-chunk)]&255;}}
    private void fat(Part p,byte[] b)throws IOException{
        int bs=u16(b,11),spc=b[13]&255,fats=b[16]&255;long total=u16(b,19)>0?u16(b,19):u32(b,32),reserved=u16(b,14),fat=u16(b,22)>0?u16(b,22):u32(b,36),root=(u16(b,17)*32L+bs-1)/bs;
        long data=total-reserved-fats*fat-root;if(bs!=disk.blockSize()||spc<1||data<1||total>p.count)throw new IOException("ANALYZER_METADATA");long clusters=data/spc;int bits=clusters<4085?12:clusters<65525?16:32;long needed=((clusters+2)*bits+7)/8;if(needed>fat*bs)throw new IOException("ANALYZER_METADATA");int active=bits==32&&(u16(b,40)&128)!=0?u16(b,40)&15:0;if(active>=fats)throw new IOException("ANALYZER_METADATA");
        field("Filesystem","نظام الملفات","FAT"+bits);field("Volume label (boot record)","اسم الوحدة (سجل الإقلاع)",ascii(b,bits==32?71:43,11));field("Volume serial (hex)","رقم الوحدة (ست عشري)",Long.toHexString(u32(b,bits==32?67:39)));size("Filesystem size","حجم نظام الملفات",total*bs);field("Cluster size (bytes)","حجم العنقود (بايت)",spc*bs);field("Data clusters / FAT copies / active FAT","عناقيد البيانات / نسخ FAT / النسخة المستخدمة",clusters+" / "+fats+" / "+active);
        if(needed>BUDGET-reads-8192){unknown();note("Allocation scan exceeds remaining 64 MiB read budget","فحص التخصيص يتجاوز ميزانية القراءة المتبقية من 64 MiB");return;}
        FatCache cache=new FatCache(p,(reserved+active*fat)*bs,needed);if(bits==16||bits==32){long flagAt=bits/8,v=0;for(int i=0;i<bits/8;i++)v|=(long)cache.get(flagAt+i)<<(i*8);boolean clean=(v&(bits==16?0x8000L:0x8000000L))!=0;field("Stored clean-shutdown flag (not a health test)","راية الإغلاق السليم المحفوظة (ليست اختبار سلامة)",clean?"Set":"Not set — space may be inconsistent",clean?"مفعلة":"غير مفعلة — قد تكون المساحة غير متسقة");}long free=0;for(long c=2;c<clusters+2;c++){if((c&4095)==0)progress.update(reads,-1);long at=c*bits/8,v=cache.get(at)|(long)cache.get(at+1)<<8;if(bits==12)v=(c&1)==0?v&4095:v>>>4;else if(bits==32)v=(v|(long)cache.get(at+2)<<16|(long)cache.get(at+3)<<24)&0xfffffffL;if(v==0)free++;}
        space(clusters*spc*bs,free*spc*bs,"Counted free clusters in the selected FAT; live metadata snapshot","عُدّت العناقيد الحرة في نسخة FAT المختارة؛ لقطة بيانات وصفية حية");
    }
    private void filesystem(Part p)throws IOException{
        byte[] b=volume(p,0,(int)Math.min(8192,p.count*disk.blockSize()));if(b.length<512){unknown();return;}String kind=signature(b);if(kind.isEmpty()&&p.count*disk.blockSize()>=65608&&ascii(volume(p,65600,8),0,8).equals("_BHRfS_M"))kind="Btrfs";
        if(kind.isEmpty()&&p.count*disk.blockSize()>=34822){byte[] vrs=volume(p,32768,2048+6);if(ascii(vrs,1,5).equals("BEA01")&&(ascii(vrs,2049,5).equals("NSR02")||ascii(vrs,2049,5).equals("NSR03")))kind="UDF";}
        if(kind.equals("FAT")){fat(p,b);return;}
        field("Filesystem","نظام الملفات",kind.isEmpty()?"Unknown / unsupported signature":kind,kind.isEmpty()?"توقيع غير معروف أو غير مدعوم":kind);
        if(kind.equals("NTFS")){int bs=u16(b,11),spc=b[13]&255;long total=u64(b,40);if(bs!=disk.blockSize()||spc<1||(spc&(spc-1))!=0||total<1||total>p.count)throw new IOException("ANALYZER_METADATA");size("Filesystem size (boot metadata)","حجم نظام الملفات (بيانات الإقلاع)",total*bs);field("Cluster size (bytes)","حجم العنقود (بايت)",spc*bs);field("NTFS serial (hex)","رقم NTFS (ست عشري)",Long.toHexString(ByteBuffer.wrap(b,72,8).order(ByteOrder.LITTLE_ENDIAN).getLong()));field("MFT cluster / mirror cluster","عنقود MFT / عنقود المرآة",u64(b,48)+" / "+u64(b,56));if(probe==null)unknown();else{BlockDevice view=new BlockDevice(){public int blockSize(){return disk.blockSize();}public long blockCount(){return p.count;}public void read(long at,byte[] data,int n)throws IOException{byte[] value=volume(p,at*blockSize(),n);System.arraycopy(value,0,data,0,n);}public void write(long at,byte[] b,int n)throws IOException{throw new IOException("READ_ONLY");}public void sync()throws IOException{throw new IOException("READ_ONLY");}public void close(){}};Space stats=probe.inspect(view);if(stats.total<1||stats.total>p.count*disk.blockSize()||stats.free<0||stats.free>stats.total)throw new IOException("ANALYZER_METADATA");field("Volume label","اسم الوحدة",stats.label);field("NTFS volume flags (hex)","رايات وحدة NTFS (ست عشري)",Integer.toHexString(stats.flags));if((stats.flags&1)!=0)note("Warning: NTFS dirty flag is set; space may be inconsistent","تحذير: راية NTFS غير المغلق سليماً مفعلة؛ قد تكون المساحة غير متسقة");space(stats.total,stats.free,"Read-only NTFS allocation bitmap via bundled NTFS-3G; live snapshot, may be inconsistent if unclean","خريطة تخصيص NTFS للقراءة فقط عبر NTFS-3G المرفق؛ لقطة حية قد تكون غير متسقة إذا لم يغلق النظام سليماً");}}
        else if(kind.equals("exFAT")){int shift=b[108]&255,cs=b[109]&255;if(shift<9||shift>12||cs>25-shift||1<<shift!=disk.blockSize())throw new IOException("ANALYZER_METADATA");long total=u64(b,72),clusters=u32(b,92);if(total>p.count||total<1||clusters<1||clusters*(1L<<cs)>total)throw new IOException("ANALYZER_METADATA");size("Filesystem size","حجم نظام الملفات",total*(1L<<shift));field("Cluster size (bytes)","حجم العنقود (بايت)",1L<<(shift+cs));field("Volume serial (hex)","رقم الوحدة (ست عشري)",Long.toHexString(u32(b,100)));field("Volume flags (hex)","رايات الوحدة (ست عشري)",Integer.toHexString(u16(b,106)));if((u16(b,106)&2)!=0)note("Warning: exFAT dirty flag is set; space may be inconsistent","تحذير: راية exFAT غير المغلق سليماً مفعلة؛ قد تكون المساحة غير متسقة");int used=b[112]&255;try{exfatSpace(p,b,shift,cs,clusters);return;}catch(IOException e){if(cancelled(e))throw e;}unknown();if(used<=100){field("Stored used percentage (approximate, may be stale)","نسبة الاستخدام المحفوظة (تقريبية وقد تكون قديمة)",used+"%");size("Estimated free allocation area (not measured)","مساحة تخصيص حرة تقديرية (غير مقاسة)",clusters*(1L<<(shift+cs))*(100-used)/100);}note("Allocation bitmap could not be fully read within limits; percentage is not exact","تعذرت قراءة خريطة التخصيص كاملة ضمن الحدود؛ النسبة ليست دقيقة");}
        else if(kind.equals("ext")){long incompat=u32(b,1120),ro=u32(b,1124),log=u32(b,1048);if(log>6)throw new IOException("ANALYZER_METADATA");long bs=1024L<<log,total=u32(b,1028),free=u32(b,1036),reserved=u32(b,1032);if((incompat&128)!=0){total|=u32(b,1360)<<32;reserved|=u32(b,1364)<<32;free|=u32(b,1368)<<32;}if(total<1||total>p.count*disk.blockSize()/bs||free<0||free>total||reserved<0||reserved>total)throw new IOException("ANALYZER_METADATA");field("Filesystem family","عائلة نظام الملفات",(incompat&64)!=0?"ext4":(u32(b,1116)&4)!=0?"ext3":"ext2");field("Volume label","اسم الوحدة",clean(new String(b,1144,16,StandardCharsets.UTF_8)));field("Filesystem UUID (raw hex)","معرف نظام الملفات (ست عشري)",hex(b,1128,16));field("Block size (bytes)","حجم الكتلة (بايت)",bs);field("Filesystem state / incompatible features / RO features (hex)","حالة النظام / السمات غير المتوافقة / سمات القراءة (ست عشري)",Integer.toHexString(u16(b,1082))+" / "+Long.toHexString(incompat)+" / "+Long.toHexString(ro));if(u16(b,1082)!=1||(incompat&4)!=0)note("Warning: ext is not marked clean or needs journal recovery; counters may be stale","تحذير: ext غير موسوم كسليم الإغلاق أو يحتاج استعادة السجل؛ قد تكون العدادات قديمة");size("Filesystem size","حجم نظام الملفات",total*bs);space(total*bs,free*bs,"Superblock counters; may be stale on an unclean/live filesystem","عدادات الكتلة الفائقة؛ قد تكون قديمة على نظام حي أو غير مغلق سليماً");size("Reserved blocks","الكتل المحجوزة",reserved*bs);size("Estimated free space excluding reserved blocks","مساحة حرة تقديرية بعد استبعاد الكتل المحجوزة",Math.max(0,free-reserved)*bs);}
        else if(kind.equals("F2FS")){field("Volume label","اسم الوحدة",utf(b,1148,Math.min(1024,b.length-1148)));unknown();note("F2FS needs checkpoint/segment accounting for free space; not inferred","تحتاج مساحة F2FS الحرة إلى حساب نقاط التحقق والمقاطع؛ لم تُخمّن");}
        else if(Arrays.asList("UDF","Btrfs","HFS+","APFS","XFS").contains(kind)){unknown();note("Signature recognized; free-space accounting is not implemented for this format","عُرف التوقيع؛ لم ينفذ حساب المساحة الحرة لهذه الصيغة");}
        else {unknown();note("Encrypted or unrecognized volumes are not decrypted or mounted","لا تُفك تشفير الوحدات المشفرة أو غير المعروفة ولا تُركب");}
    }
    private long exfatNext(Part p,long cluster,long fat,long fatSectors,long clusters)throws IOException{if(cluster<2||cluster>=clusters+2||cluster*4+4>fatSectors*disk.blockSize())throw new IOException("ANALYZER_METADATA");return u32(volume(p,fat*disk.blockSize()+cluster*4,4),0);}
    private void exfatSpace(Part p,byte[] boot,int shift,int cs,long clusters)throws IOException{
        int fats=boot[110]&255,active=u16(boot,106)&1;long fat=u32(boot,80),fatSectors=u32(boot,84),heap=u32(boot,88),root=u32(boot,96),clusterBytes=1L<<(shift+cs),volumeSectors=u64(boot,72);
        if(fats<1||fats>2||active>=fats||fat<24||fatSectors<1||heap<fat+fatSectors*fats||heap+clusters*(1L<<cs)>volumeSectors)throw new IOException("ANALYZER_METADATA");fat+=active*fatSectors;
        long bitmap=0,bitmapSize=0;Set<Long> seen=new HashSet<>();boolean end=false;
        while(!end&&bitmap==0){if(root<2||root>=clusters+2||!seen.add(root)||seen.size()>4096)throw new IOException("ANALYZER_METADATA");long base=(heap+(root-2)*(1L<<cs))*(1L<<shift);
            for(long offset=0;offset<clusterBytes&&!end&&bitmap==0;offset+=4096){int n=(int)Math.min(4096,clusterBytes-offset);byte[] data=volume(p,base+offset,n);for(int at=0;at+32<=n;at+=32){int type=data[at]&255;if(type==0){end=true;break;}if(type==0x83&&(data[at+1]&255)<=11)field("Volume label","اسم الوحدة",utf(data,at+2,(data[at+1]&255)*2));if(type==0x81&&(data[at+1]&1)==active){bitmap=u32(data,at+20);bitmapSize=u64(data,at+24);break;}}}
            if(!end&&bitmap==0){root=exfatNext(p,root,fat,fatSectors,clusters);if(root>=0xfffffff8L)end=true;}
        }
        long needed=(clusters+7)/8;if(bitmap<2||bitmapSize!=needed||needed>BUDGET-reads-8192)throw new IOException("ANALYZER_LIMIT");long remaining=needed,bits=clusters,allocated=0;seen.clear();
        while(remaining>0){if(bitmap<2||bitmap>=clusters+2||!seen.add(bitmap)||seen.size()>65536)throw new IOException("ANALYZER_METADATA");long base=(heap+(bitmap-2)*(1L<<cs))*(1L<<shift),take=Math.min(clusterBytes,remaining);
            for(long offset=0;offset<take;offset+=65536){int n=(int)Math.min(65536,take-offset);byte[] data=volume(p,base+offset,n);for(byte item:data){int count=(int)Math.min(8,bits);if(count==0)break;allocated+=Integer.bitCount((item&255)&((1<<count)-1));bits-=count;}}
            remaining-=take;if(remaining>0)bitmap=exfatNext(p,bitmap,fat,fatSectors,clusters);
        }
        space(clusters*clusterBytes,(clusters-allocated)*clusterBytes,"Counted allocated bits in active exFAT bitmap; live metadata snapshot","عُدّت بتات التخصيص في خريطة exFAT النشطة؛ لقطة بيانات وصفية حية");
    }
    private static String hex(byte[] b,int at,int n){StringBuilder s=new StringBuilder();for(int i=at;i<at+n;i++)s.append(String.format(Locale.ROOT,"%02x",b[i]&255));return s.toString();}
    private static String utc(){java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'",Locale.ROOT);f.setTimeZone(TimeZone.getTimeZone("UTC"));return f.format(new Date());}
    public String analyze()throws IOException{
        int bs=disk.blockSize();if((bs!=512&&bs!=4096)||disk.blockCount()<1||disk.blockCount()>Long.MAX_VALUE/bs)throw new IOException("UNSUPPORTED_CAPACITY");
        note("Full USB analyzer — read-only report","محلل USB الشامل — تقرير للقراءة فقط");field("Device time (UTC, not certified)","وقت الجهاز (UTC، غير معتمد)",utc());size("Reported drive capacity","سعة الوحدة المبلغ عنها",disk.blockCount()*bs);field("Logical sector size (bytes)","حجم القطاع المنطقي (بايت)",bs);field("Addressable sectors","القطاعات القابلة للعنونة",disk.blockCount());
        try{byte[] first=read(0,(int)Math.min(4096,disk.blockCount()*bs));boolean gpt=disk.blockCount()>1&&ascii(read(bs,8),0,8).equals("EFI PART"),protective=false;for(int i=0;i<4;i++)if(u16(first,510)==0xaa55&&signature(first).isEmpty()&&(first[450+i*16]&255)==238)protective=true;
        if(gpt||protective)gpt();else if(!signature(first).isEmpty()){field("Partition table","جدول الأقسام","Raw whole-drive filesystem","نظام ملفات على كامل الوحدة دون جدول");parts.add(new Part(0,0,disk.blockCount()));}
        else if(u16(first,510)==0xaa55)mbr(first);else{field("Partition table","جدول الأقسام","Unknown / no recognized table","غير معروف / لا يوجد جدول معروف");parts.add(new Part(0,0,disk.blockCount()));}
        }catch(IOException e){if(cancelled(e))throw e;field("Technical error code","رمز الخطأ التقني",e.getMessage());note("Disk layout analysis incomplete: read error, malformed metadata or limit; no repair performed","تحليل تخطيط القرص غير مكتمل: خطأ قراءة أو بيانات وصفية غير صالحة أو حد التحليل؛ لم يُجر إصلاح");}
        List<Part> sorted=new ArrayList<>(parts);Collections.sort(sorted,(a,b)->Long.compare(a.first,b.first));long union=0,end=0;boolean overlap=false;for(Part p:sorted){if(p.first<end)overlap=true;long last=p.first+p.count;if(last>end)union+=last-Math.max(end,p.first);end=Math.max(end,last);}field("Analyzed volumes","الوحدات التي جرى تحليلها",parts.size());if(!parts.isEmpty())size("Outside listed volumes (includes table/boot gaps; not filesystem free space)","خارج الوحدات المدرجة (يشمل فجوات الجداول والإقلاع؛ ليس مساحة ملفات حرة)",(disk.blockCount()-union)*bs);if(overlap)note("Warning: overlapping partitions; space totals must not be added","تحذير: أقسام متداخلة؛ لا تجمع مساحاتها");
        for(Part p:parts){field("Volume / partition number","رقم الوحدة / القسم",p.number);field("First / last LBA","أول / آخر LBA",p.first+" / "+(p.first+p.count-1));size("Partition capacity","سعة القسم",p.count*bs);try{filesystem(p);}catch(IOException e){if(cancelled(e))throw e;field("Technical error code","رمز الخطأ التقني",e.getMessage());field("Volume analysis incomplete","تحليل الوحدة غير مكتمل","Read error, malformed metadata, or analysis limit; no repair performed","خطأ قراءة أو بيانات وصفية غير صالحة أو حد التحليل؛ لم يُجر إصلاح");unknown();}}
        field("Read request bytes (maximum 64 MiB, includes failed requests)","بايتات طلبات القراءة (حتى 64 MiB، تشمل الطلبات الفاشلة)",reads);note("Live metadata snapshot, not a full surface scan or file inventory; no drive writes","لقطة بيانات وصفية حية وليست فحصاً لكل القطاعات أو جرداً للملفات؛ لم تُكتب الوحدة");note("USB IDs/serials and capacity can be spoofed. SMART, flash wear, real capacity, hidden cells, speed and bootability are not established","يمكن تزوير معرفات USB وأرقامها وسعتها. لم تُحدد SMART أو تآكل الفلاش أو السعة الحقيقية أو الخلايا المخفية أو السرعة أو قابلية الإقلاع");progress.update(reads,reads);return out.toString();
    }
    public static String render(String report,boolean ar){StringBuilder s=new StringBuilder();for(String line:report.substring(PREFIX.length()).split("\n")){String[] f=line.split("\t",-1);if(f.length!=4)continue;String label=f[ar?1:0],value=f[ar?3:2];s.append(label);if(!value.isEmpty())s.append(": ").append(value);s.append('\n');}return s.toString();}
}
